const {
  githubApiErrorStatus,
  withGithubApiRetry,
} = require(path.join(
  process.env.GITHUB_WORKSPACE,
  "tools/ci/github-api-retry.cjs",
));

async function githubApi(label, run) {
  return withGithubApiRetry(run, {
    onRetry: ({ attempt, maxAttempts, delayMs, error }) => {
      const status = githubApiErrorStatus(error);
      core.warning(
        `GitHub API ${label} returned ${status ?? "5xx"}; retrying in ${delayMs}ms (attempt ${attempt}/${maxAttempts}).`,
      );
    },
  });
}

const eventName = process.env.EVENT_NAME;
let envName;
if (eventName === "pull_request") {
  const n = process.env.PR_NUMBER;
  if (!n) {
    core.info("No PR number on event; skipping GitHub deployment delete.");
    return;
  }
  envName = `preview-${n}`;
} else if (
  eventName === "workflow_dispatch" &&
  process.env.INPUT_TARGET === "pr"
) {
  const n = process.env.INPUT_PR_NUMBER;
  if (!n) {
    core.info(
      "Manual cleanup without pr_number; skipping GitHub deployment delete.",
    );
    return;
  }
  envName = `preview-${n}`;
} else {
  core.info(
    "Skipping GitHub deployment delete (branch-targeted cleanups use a different naming scheme).",
  );
  return;
}

const { owner, repo } = context.repo;
const deployments = await githubApi("listDeployments", () =>
  github.paginate(github.rest.repos.listDeployments, {
    owner,
    repo,
    environment: envName,
    per_page: 100,
  }),
);

for (const deployment of deployments) {
  try {
    await githubApi("deleteDeployment", () =>
      github.rest.repos.deleteDeployment({
        owner,
        repo,
        deployment_id: deployment.id,
      }),
    );
  } catch (error) {
    // A 5xx after a successful delete surfaces as 404 on retry.
    if (error.status === 404) continue;
    if (error.status !== 422) throw error;
    await githubApi("createDeploymentStatus", () =>
      github.rest.repos.createDeploymentStatus({
        owner,
        repo,
        deployment_id: deployment.id,
        state: "inactive",
        description: "Cleaning up closed PR preview deployment.",
      }),
    );
    try {
      await githubApi("deleteDeployment", () =>
        github.rest.repos.deleteDeployment({
          owner,
          repo,
          deployment_id: deployment.id,
        }),
      );
    } catch (retryError) {
      if (retryError.status !== 404) throw retryError;
    }
  }
}

core.notice(
  `Deleted ${deployments.length} GitHub preview deployment(s) for ${envName}.`,
);

