  "tools/ci/github-api-retry.cjs",
));

async function githubApi(label, run) {
  return withGithubApiRetry(run, {
    onRetry: ({ attempt, maxAttempts, delayMs, error }) => {
      const status = githubApiErrorStatus(error);
      core.warning(
        `GitHub API ${label} returned ${status ?? "5xx"}; retrying in ${delayMs}ms (attempt ${attempt}/${maxAttempts}).`,
      );
    },
  });
}

const eventName = process.env.EVENT_NAME;
const hasAdminToken =
  process.env.HAS_PREVIEW_ENVIRONMENT_ADMIN_TOKEN === "true";
let envName;
if (eventName === "pull_request") {
  const n = process.env.PR_NUMBER;
  if (!n) {
    core.info("No PR number on event; skipping GitHub environment delete.");
    return;
  }
  envName = `preview-${n}`;
} else if (
  eventName === "workflow_dispatch" &&
  process.env.INPUT_TARGET === "pr"
) {
  const n = process.env.INPUT_PR_NUMBER;
  if (!n) {
    core.info(
      "Manual cleanup without pr_number; skipping GitHub environment delete.",
    );
    return;
  }
  envName = `preview-${n}`;
} else {
  core.info(
    "Skipping GitHub environment delete (branch-targeted cleanups use a different naming scheme).",
  );
  return;
}

if (!hasAdminToken) {
  core.warning(
    `PREVIEW_ENVIRONMENT_ADMIN_TOKEN is required to delete leftover GitHub preview environment ${envName}. Configure it with repository administration write access.`,
  );
  return;
}

const { owner, repo } = context.repo;
try {
  await githubApi("deleteEnvironment", () =>
    github.request(
      "DELETE /repos/{owner}/{repo}/environments/{environment_name}",
      {
        owner,
        repo,
        environment_name: envName,
      },
    ),
  );
  core.notice(`Deleted GitHub environment: ${envName}`);
} catch (e) {
  if (e.status === 404) {
    core.warning(
      `Could not confirm deletion of GitHub environment ${envName}; it may already be absent or the token may lack access.`,
    );
  } else if (
    e.status === 403 &&
    e.response?.headers?.["x-accepted-github-permissions"] ===
      "administration=write"
  ) {
    core.warning(
      `PREVIEW_ENVIRONMENT_ADMIN_TOKEN cannot delete ${envName}; it must allow repository administration write access.`,
    );
  } else {
    throw e;
  }
}

